package com.rohit.inventory.security;
import static org.assertj.core.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test; import org.springframework.security.core.authority.SimpleGrantedAuthority;
class JwtServiceTest { @Test void generatesSignedExpiringTokenWithMinimalClaims(){JwtService service=new JwtService("test-only-secret-with-at-least-thirty-two-bytes",3600,"test-issuer");UUID id=UUID.randomUUID();String token=service.generate(id,"admin@example.com",List.of(new SimpleGrantedAuthority("ROLE_ADMIN"),new SimpleGrantedAuthority("USER_READ")));var claims=service.parse(token);assertThat(claims.getSubject()).isEqualTo("admin@example.com");assertThat(claims.get("userId",String.class)).isEqualTo(id.toString());assertThat(claims.get("roles",List.class)).containsExactly("ADMIN");assertThat(claims.getExpiration()).isAfter(new Date());} @Test void rejectsTooShortSecret(){assertThatThrownBy(()->new JwtService("too-short",3600,"issuer")).isInstanceOf(IllegalStateException.class);} }
